// Merge avatar and product base64 data
const avatarData = $('Extract Avatar to Base64').first().json;
const productData = $('Extract Product to Base64').first().json;
const promptData = $('video_prompt').first().json;

return {
  avatar_binary: avatarData.avatar_binary,
  product_binary: productData.product_binary,
  video_prompt: promptData.output.video_prompt
};

